package com.novacommerce.order.infrastructure.persistence; import com.novacommerce.order.domain.cart.*; import jakarta.persistence.LockModeType; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface CartRepository extends JpaRepository<Cart,UUID>{@Query("select c from Cart c where c.ownerId=:owner and c.status in (com.novacommerce.order.domain.cart.CartStatus.ACTIVE,com.novacommerce.order.domain.cart.CartStatus.CHECKOUT_PENDING)")Optional<Cart> findOpen(@Param("owner")UUID owner);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select c from Cart c where c.id=:id and c.ownerId=:owner")Optional<Cart> lockOwned(@Param("id")UUID id,@Param("owner")UUID owner);}
